 function reset(q:Question){if(recordingRef.current)return;setAssessmentError('');cancelTranscription();setSelected(q);setAudio(null);setAudioUrl('');if(audioUrlRef.current)URL.revokeObjectURL(audioUrlRef.current);audioUrlRef.current='';setAttemptId('');setFeedback(null);setTranscript('');setSegments([]);setInterim('');setNotes('');setTypedAnswer('');setMicError(null);setElapsed(0);seconds.current=0;original.current='';setHint(false);setSpeechStatus('');setPrep(null)}
