  if(!SR){setSpeechStatus(data.aiConfigured?'Automatic audio transcription starts shortly.':'Live transcription is unavailable in this browser. Connect AI for automatic audio transcription.');return;}
  const r=new SR();recognition.current=r;r.continuous=true;r.interimResults=true;r.lang=speechLanguage==='auto'?'en-US':speechLanguage;let base='',current='',restarts=0,blocked=false;
  r.onresult=(event:any)=>{if(id!==transcriptSession.current)return;restarts=0;const text=recognizedText(event);current=text.final;if(!cloudSeen.current){original.current=[base,current].filter(Boolean).join(' ');setTranscript(original.current);interimRef.current=text.interim;setInterim(text.interim);setSpeechStatus('Listening · live transcript');}};
