   {(reviewFilter==='all'||reviewFilter==='answers')&&data.attempts.filter((a:any)=>a.feedback).map((a:any)=><div className="review-item" key={a.id}><span className="stat-icon sage"><Sparkles size={22}/></span><div><Pill tone={a.reviewed?'neutral':'peach'}>{a.reviewed?'Reviewed':'Needs review'}</Pill><h3>{bank.find(q=>q.id===a.question_id)?.text||'Speaking answer'}</h3><p>{a.feedback.summary}</p></div><Button secondary onClick={()=>loadAttempt(a)}>Review <ArrowRight size={15}/></Button></div>)}
